def main():
    md=(AQUI/"roteiro.md").read_text(encoding="utf-8"); tx={}
    for l in md.splitlines():
        m=re.match(r"^(\d+)\. (.*)",l)
        if m: tx[int(m.group(1))]=re.sub(r"\s*\[[^\]]*\]","",m.group(2)).strip()
    out=[{"cena":n,"texto":tx[n],"prompt":S[n][2],"ref2":S[n][1],"perso":S[n][0],"cartao":S[n][2].startswith("Empty plain space")} for n in range(1,168)]
    (AQUI/"prompts_local.json").write_text(json.dumps(out,indent=1,ensure_ascii=False),encoding="utf-8")
    print(len(out),sum(len(o["texto"].split())>17 for o in out),"com b")
main()

